interface ReadParts<A, V> {
  readonly load: (args: A) => Promise<void>;
  readonly refresh: () => Promise<void>;
  readonly isLoaded: Signal<boolean>;
  readonly value: Signal<V>;
  readonly isLoading: Signal<boolean>;
  readonly error: Signal<ProblemDetails | null>;
  readonly kept: KeptGate | null;
}

/** *key*'s parts of a list or single-result *route*, covered by *kept* when the route is a `cached` read. */
function connectRead<A extends object, R, V>(
  store: Store,
  route: ReadRoute<A, R, V>,
  key: string,
  empty: V,
  kept: KeptRead | undefined,
): ReadParts<A, V> {
  lease(store, route.leases, key, route.release);
  const request = store.selectSignal(route.request(key));
  const parts = {
    load: (args: A) => dispatchSettled(store, route.settled, key, (requestId) => route.load({ key, requestId, args })),
    refresh: () => {
      const { args } = loaded(route.route, key, 'refresh', request);
      return dispatchSettled(store, route.settled, key, (requestId) => route.load({ key, requestId, args }));
    },
    isLoaded: computed(() => request()?.answered != null),
    value: store.selectSignal(route.value(key)),
    isLoading: computed(() => request()?.status === 'loading'),
    error: computed(() => request()?.error ?? null),
  };
  if (kept === undefined) {
    return { ...parts, kept: null };
  }
  const { copies: _copies, ...covered } = keptValue(parts, kept, empty, plainCodec<V>());
  return covered;
}

/** Connect *key* of the list *route* (module comment); *kept* covers it when the route is a `cached` read. */
export function connectList<A extends object, R, T>(
  store: Store,
  route: ReadRoute<A, R, readonly T[]>,
  key: string,
  kept?: KeptRead,
): ListHandle<A, T> {
  requireKey(key, route.route);
  assertInInjectionContext(connectList);
  const { value, ...parts } = connectRead(store, route, key, [], kept);
  return { ...parts, rows: value };
}

/** Connect *key* of the single-result *route* (module comment); *kept* covers it when the route is a `cached` read. */
export function connectSingle<A extends object, R, V>(
  store: Store,
  route: ReadRoute<A, R, V | null>,
  key: string,
  kept?: KeptRead,
): SingleHandle<A, V> {
  requireKey(key, route.route);
  assertInInjectionContext(connectSingle);
  return connectRead(store, route, key, null, kept);
}

/**
 * The single-result handle of a binding over a read no state holds -- one answering bytes:
 * each load calls the route's client method through *call*, a newer load replaces the one in
 * flight, an answer keeps being shown while a newer load runs or fails, and the calling
 * component's destruction cancels what is in flight (so it is called in an injection context).
 * `refresh()` resolves once its load has settled: answered, failed, replaced or cancelled.
 * *kept* covers it when the route is a `cached` read of the app, keeping each answer by its codec.
 */
export function clientRead<A extends object, V>(
  route: string,
  call: (args: A) => Observable<V>,
  kept?: { readonly read: KeptRead; readonly codec: KeptCodec<V> },
): SingleHandle<A, V> {
  assertInInjectionContext(clientRead);
  const answer = signal<{ readonly value: V } | null>(null);
  const loading = signal(false);
  const failure = signal<ProblemDetails | null>(null);
  let sent: { readonly args: A } | null = null;
  let inFlight: { readonly subscription: Subscription; readonly settle: () => void } | null = null;
  const cancel = (): void => {
    inFlight?.subscription.unsubscribe();
    inFlight?.settle();
    inFlight = null;
  };
  const load = (args: A): Promise<void> => {
    cancel();
    sent = { args };
    loading.set(true);
    return new Promise<void>((settle) => {
      const done = (): void => {
        loading.set(false);
        inFlight = null;
        settle();
      };
      const subscription = call(args).subscribe({
        next: (value) => {
          answer.set({ value });
          failure.set(null);
        },
        error: (error: unknown) => {
          failure.set(problemFromError(error));
          done();
        },
        complete: done,
      });
      if (!subscription.closed) {
        inFlight = { subscription, settle };
      }
    });
  };
  inject(DestroyRef).onDestroy(cancel);
  const parts = {
    load,
    refresh: () => {
      if (sent === null) {
        throw new Error(`${route}: refresh() before the first load; a view refreshes a binding only once it has loaded.`);
      }
      return load(sent.args);
    },
    isLoaded: computed(() => answer() !== null),
    value: computed(() => answer()?.value ?? null),
    isLoading: loading.asReadonly(),
    error: failure.asReadonly(),
  };
  if (kept === undefined) {
    return { ...parts, kept: null };
  }
  const nullable: KeptCodec<V | null> = {
    encode: (copy) => (copy === null ? Promise.resolve(null) : kept.codec.encode(copy)),
    decode: (stored) => (stored === null ? null : kept.codec.decode(stored)),
  };
  const { copies: _copies, ...covered } = keptValue<A, V | null>(parts, kept.read, null, nullable);
  return covered;
}

/** Connect *key* of the write *route* (module comment). */
export function connectMutation<A, R>(store: Store, route: MutationRoute<A, R>, key: string): MutationHandle<A, R> {
  requireKey(key, route.route);
  assertInInjectionContext(connectMutation);
  lease(store, route.leases, key, route.release);
  const state = store.selectSignal(route.state(key));
  const settle = (args: A): Promise<Settlement<R>> => {
    const requestId = nextRequestId();
    // Listen before dispatching, so an answer settled synchronously is still seen.
    const settlement = firstValueFrom(route.settled(requestId));
    store.dispatch(route.submit({ key, requestId, args }));
    return settlement;
  };
  return {
    submit: async (args) => {
      const ended = await settle(args);
      if ('problem' in ended) {
        throw ended.problem;
      }
      return ended.result;
    },
    call: async (args) => {
      const ended = await settle(args);
      if ('problem' in ended) {
        throw toDomainError(ended.problem);
      }
      return ended.result;
    },
    pending: computed(() => (state()?.inFlight.length ?? 0) > 0),
    error: computed(() => state()?.error ?? null),
    lastResult: computed(() => state()?.lastResult ?? null),
  };
}
